<?php $this->servers->_display('pending', $viewData); ?>
<section class="card"><h2>Servers</h2><?php if (!$inventory['servers'] && !$pending_servers): ?><p>No servers connected yet. <a href="/servers">Connect your first server</a>.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Server</th><th>Address</th><th>Readiness</th></tr></thead><tbody><?php foreach ($inventory['servers'] as $server): ?><tr><td><a href="/servers/details?server=<?= $e(rawurlencode($server['id'])) ?>"><?= $e($server['id']) ?></a></td><td><?= $e($server['host']) ?></td><td><?= $e(!empty($server['builder_ready'])?'Ready for builds':($server['application_ready']?'Ready for apps':implode(', ',$server['missing']))) ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
